
import {sources,appNames,records,available,appRecords,within,summarize,priority,daysUntil,moduleSources} from './operational.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gbp=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(v);
export const opsState={app:'app-policy',source:'servicenow',months:6,severity:'All',status:'All',page:0,include:true};
const button=(app,label='Explore application evidence')=>'<button class="btn" data-app-evidence="'+esc(app)+'">'+esc(label)+'</button>';
const apps=g=>g.nodes.filter(n=>appRecords(g,n.id).length);
function table(headers,rows){return '<div class="table-wrap"><table class="table"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';}
export function applicationSummary(g,id){
 let targets=appRecords(g,id).length?[id]:g.edges.filter(e=>e.target===id&&e.state==='observed'&&e.type==='DEPENDS_ON'&&appRecords(g,e.source).length).map(e=>e.source);
 targets=[...new Set(targets)];
 return '<section class="signal-evidence"><h3>Signals &amp; Evidence</h3><p>Six-month synthetic evidence · May–October 2026, through 29 October.</p>'+ (targets.length?targets.map(app=>{const s=summarize(g,app);return '<div class="evidence"><strong>'+esc(appNames[app])+'</strong><p>'+s.tickets.length+' tickets · '+s.counts.P1+' P1 · '+s.counts.P2+' P2<br>'+s.critical.length+' open high/critical security findings<br>'+s.renewals.length+' contracts renewing within 90 days<br>'+s.failed+'/'+s.runs.length+' failed pipelines</p>'+button(app,'Dig into '+appNames[app])+'</div>';}).join(''):'<p>No operational sample records mapped to this entity. Select an application or its directly linked technology.</p>')+'</section>';
}
export function evidenceView(g){
 const options=apps(g);if(!options.length)return '<h1>Application evidence</h1><p>No synthetic application matches in this context. Your imported graph is not automatically linked to demo records.</p>';
 if(!options.some(n=>n.id===opsState.app))opsState.app=options[0].id;
 const id=opsState.app,s=summarize(g,id,opsState.months),p=priority(g,id),period='2026-'+String(11-opsState.months).padStart(2,'0')+'-01 to 2026-10-29';
 const monthly=Array.from({length:opsState.months},(_,i)=>String(11-opsState.months+i).padStart(2,'0'));
 const context=g.edges.filter(e=>e.source===id||e.target===id).map(e=>{const other=g.nodes.find(n=>n.id===(e.source===id?e.target:e.source));return other?'<button class="btn" data-graphnode="'+esc(other.id)+'">'+esc(g.nodes.find(n=>n.id===e.source)?.name)+' → '+esc(e.type.replaceAll('_',' '))+' → '+esc(g.nodes.find(n=>n.id===e.target)?.name)+' ('+esc(e.state||'unspecified')+')'+'</button>':'';}).join('');
 return '<div class="heading"><div><div class="eyebrow">Application intelligence · linked source evidence</div><h1>'+esc(appNames[id])+' — application evidence</h1><p class="subtitle">Inspect operational facts, follow enterprise relationships and review decision implications.</p></div></div><div class="toolbar"><label>Application <select class="select" id="ops-app" aria-label="Application">'+options.map(n=>'<option value="'+n.id+'" '+(id===n.id?'selected':'')+'>'+esc(n.name)+'</option>').join('')+'</select></label><label>Evidence window <select class="select" id="ops-months" aria-label="Evidence window">'+[1,3,6].map(n=>'<option value="'+n+'" '+(opsState.months===n?'selected':'')+'>'+n+' calendar month'+(n>1?'s':'')+'</option>').join('')+'</select></label><button class="btn" data-graphnode="'+id+'">Open application graph</button></div><div class="data-health">All records are fictional. Window: '+period+'. October is partial. Status is the snapshot status on 29 October, not historical status at each month end. No live connectors.</div><div class="ops-metrics">'+[['Incidents raised',s.tickets.length,s.openTickets+' still open'],['High / critical security',s.critical.length,'Open at snapshot'],['Failed pipeline runs',s.failed+'/'+s.runs.length,'Within evidence window'],['Renewals within 90 days',s.renewals.length,'From snapshot date'],['Projects with blockers',s.blocked.length,'Blocked status or blocked items'],['Cloud allocation',gbp(s.spend),'Window total; not total run cost']].map(([k,v,n])=>'<div class="panel signal-card"><small>'+k+'</small><h2>'+v+'</h2><small>'+n+'</small></div>').join('')+'</div><section class="panel signal-card section-gap"><h2>ServiceNow incidents by month and severity</h2><p>P1 critical · P2 high · P3 medium · P4 low in this demo. Counts are based on date raised, including resolved incidents.</p>'+table(['Month','P1','P2','P3','P4','Total'],monthly.map(mm=>{const rs=s.tickets.filter(r=>r.date.slice(5,7)===mm);return '<tr><td>2026-'+mm+'</td>'+['P1','P2','P3','P4'].map(pr=>'<td>'+rs.filter(r=>r.severity===pr).length+'</td>').join('')+'<td>'+rs.length+'</td></tr>';}) .concat(['<tr><th>Total</th>'+['P1','P2','P3','P4'].map(pr=>'<td><button class="text-button" data-ops-severity="'+pr+'">'+pr+': '+s.counts[pr]+'</button></td>').join('')+'<td>'+s.tickets.length+'</td></tr>']))+'</section><div class="grid-two section-gap"><section class="panel signal-card"><h2>Connected enterprise context</h2><p>These are recorded relationships, not inferred root causes.</p><div class="buttons">'+context+'</div><button class="btn primary" data-impact="'+id+'">Trace business impact</button></section><section class="panel signal-card"><h2>How this changes a CIO review</h2><p>Application Portfolio review priority: <b>'+p.base+' → '+p.score+'</b> / 100, using the full six-month snapshot. This is a review heuristic, not a probability or approval.</p><ul>'+p.drivers.map(d=>'<li>'+esc(d.label)+' (+'+d.points+')</li>').join('')+'</ul><p>Combined uplift capped at 25; final score capped at 100. Existing business value, health and risk scores remain visible as the baseline.</p><button class="btn" data-page="module-applications">Compare application priorities</button></section></div>'+recordExplorer(g,s.all)+'<section class="panel signal-card section-gap"><h2>Contract renewal watch</h2>'+table(['Contract','Renewal','Notice deadline','Status','Annual value'],s.contracts.map(r=>'<tr><td>'+esc(r.id)+'</td><td>'+r.renewalDate+' ('+daysUntil(r.renewalDate)+' days)</td><td>'+r.noticeDate+(daysUntil(r.noticeDate)<0?' · elapsed':'')+'</td><td>'+esc(r.status)+'</td><td>'+gbp(r.annualAmountGBP)+'</td></tr>'))+'<p>Elapsed notice dates flag review; this demo does not infer legal consequences or auto-renewal.</p></section>';
}
function recordExplorer(g,all){
 let filtered=all.filter(r=>r.source===opsState.source&&(opsState.severity==='All'||r.severity===opsState.severity)&&(opsState.status==='All'||r.status===opsState.status));
 filtered.sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));
 const max=Math.max(0,Math.ceil(filtered.length/15)-1);opsState.page=Math.min(max,opsState.page);
 const rows=filtered.slice(opsState.page*15,opsState.page*15+15);
 const statuses=[...new Set(all.filter(r=>r.source===opsState.source).map(r=>r.status))];
 return '<section class="panel signal-card section-gap" id="source-records"><h2>Source records</h2><div class="signal-sources">'+sources.map(([key,label])=>'<button class="signal-source '+(opsState.source===key?'selected':'')+'" data-ops-source="'+key+'" aria-pressed="'+(opsState.source===key)+'"><strong>'+label+'</strong><small>'+all.filter(r=>r.source===key).length+' records</small></button>').join('')+'</div><div class="toolbar"><label>Severity <select class="select" id="ops-severity" aria-label="Severity">'+['All','P1','P2','P3','P4','Critical','High','Medium','Low'].map(x=>'<option '+(x===opsState.severity?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>Status <select class="select" id="ops-status" aria-label="Status">'+['All',...statuses].map(x=>'<option '+(x===opsState.status?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label><span>'+filtered.length+' matching records</span><button class="btn" data-action="export-operational">Export application evidence</button></div>'+table(['Record / evidence','Raised / observed','Type','Severity','Status'],rows.map(r=>'<tr><td><details><summary>'+esc(r.id)+' · '+esc(r.title)+'</summary><dl class="record-details">'+Object.entries(r).map(([key,value])=>'<dt>'+esc(key)+'</dt><dd>'+esc(value)+'</dd>').join('')+'</dl><p>Provenance: manually authored synthetic fixture. Application mapping: exact demo ID. Not owner validated.</p></details></td><td>'+r.date+'</td><td>'+r.kind+'</td><td>'+esc(r.severity||'—')+'</td><td>'+esc(r.status)+'</td></tr>'))+(rows.length?'':'<p>No records match these filters.</p>')+'<div class="buttons"><button class="btn" data-ops-page="-1" '+(opsState.page===0?'disabled':'')+'>Previous records</button><span>Page '+(opsState.page+1)+' of '+(max+1)+'</span><button class="btn" data-ops-page="1" '+(opsState.page===max?'disabled':'')+'>Next records</button></div></section>';
}
export function enterpriseSignals(g){const list=apps(g);return '<div class="heading"><div><div class="eyebrow">Evidence behind the enterprise graph</div><h1>Enterprise Signals</h1><p class="subtitle">Six months of connected application records across seven source families.</p></div></div><div class="data-health">Synthetic demo dataset · '+list.reduce((count,n)=>count+appRecords(g,n.id).length,0)+' source records · 1 May–29 October 2026 · No live connectors. Records are linked by application ID; they are not evidence of causation.</div><div class="signal-sources">'+sources.map(([id,name])=>'<div class="panel signal-card"><h2>'+name+'</h2><p>'+list.reduce((n,a)=>n+appRecords(g,a.id).filter(r=>r.source===id).length,0)+' records</p></div>').join('')+'</div><section class="panel signal-card"><h2>Choose an application to investigate</h2>'+table(['Application','Tickets raised','P1 / P2 / P3 / P4','Open high/critical findings','Renewals ≤90d',''],list.map(n=>{const s=summarize(g,n.id);return '<tr><td><button class="text-button" data-graphnode="'+n.id+'">'+esc(n.name)+'</button></td><td>'+s.tickets.length+'</td><td>'+Object.values(s.counts).join(' / ')+'</td><td>'+s.critical.length+'</td><td>'+s.renewals.length+'</td><td>'+button(n.id,'Investigate '+n.name)+'</td></tr>';}))+'</section>';}
export function moduleOperational(g,id){const ns=apps(g);if(!ns.length)return '';const ranked=ns.map(n=>({...priority(g,n.id,id,opsState.include),name:n.name})).sort((a,b)=>(b.score??-1)-(a.score??-1)||a.name.localeCompare(b.name));
 return '<section class="panel signal-card section-gap"><h2>Operational evidence changes review priority</h2><p>Six-month synthetic snapshot. Sources used here: '+(moduleSources[id]||[]).map(k=>sources.find(s=>s[0]===k)[1]).join(', ')+'. This review queue complements the module; it does not implement its full analytical engine.</p><label><input type="checkbox" id="ops-include" '+(opsState.include?'checked':'')+'> Include operational evidence in review priority</label><p>Baseline = 45% risk + 35% technical weakness + 20% business value. Uplift = source rules below, capped at 25; total capped at 100. Missing baseline scores remain unknown. All source records need owner review.</p><details><summary>Show scoring rules</summary><p>Incidents: min(12, 2 × P1 + 0.5 × P2); security: min(10, 3 × open high/critical); finance: min(8, 5 × renewals within 90 days + 3 × pending renewals with elapsed notice dates); delivery: min(6, 3 × projects with blockers); pipelines: +6 if failure rate &gt;20%; cloud: +5 if CPU &lt;25%; architecture: +4 if lifecycle is Modernize. Only this module’s listed sources count. These are illustrative prioritization rules, not a production risk model.</p></details>'+table(['Application','Baseline','With selected evidence','Reasons / source drill-down','Action'],ranked.map(p=>'<tr><td>'+esc(p.name)+(p.needsReview?'<br><span class="tag orange">Baseline unvalidated</span>':'')+'</td><td>'+p.base+'</td><td class="ops-score">'+p.score+' <small>(+'+p.uplift+')</small></td><td>'+p.drivers.map(d=>'<button class="connection" data-app-evidence="'+p.app+'" data-evidence-source="'+d.source+'">'+esc(d.label)+' · '+d.ids.length+' evidence records</button>').join('')+'</td><td>'+button(p.app,'Inspect evidence')+'<button class="btn" data-ops-decision="'+p.app+'" data-module="'+id+'">Create evidence review</button></td></tr>'))+'</section>';
}
